+
+import com.microsoft.playwright.Browser;
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.Playwright;
+import com.microsoft.playwright.assertions.PlaywrightAssertions;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserTest {
+
+    static Playwright playwright;
+    static Browser browser;
+
+    @LocalServerPort
+    int port;
+
+    @BeforeAll
+    static void start() {
+        playwright = Playwright.create();
+        browser = playwright.chromium().launch();
+    }
+
+    @AfterAll
+    static void stop() {
+        browser.close();
+        playwright.close();
+    }
+
+    @Test
+    void sendAndLeave() {
+        Page page = browser.newPage();
+        page.navigate("http://localhost:" + port + "/contact");
+        var send = page.locator("vaadin-button", new Page.LocatorOptions().setHasText("Send"));
+        PlaywrightAssertions.assertThat(page.locator("h1")).hasText("Contact");
+        send.click();
+        PlaywrightAssertions.assertThat(page.locator("vaadin-text-field").first()).hasAttribute("invalid", "");
+        PlaywrightAssertions.assertThat(page.getByText("Name is required")).isVisible();
+
+        page.getByLabel("Name").fill("Carol");
+        page.getByLabel("Email").fill("carol@example.com");
+        page.getByLabel("Message").fill("Hi from browser");
+        page.getByLabel("Name").press("Enter");
+        PlaywrightAssertions.assertThat(page.locator("vaadin-notification-card")).containsText("Message sent");
+        PlaywrightAssertions.assertThat(send).isDisabled();
+        PlaywrightAssertions.assertThat(page.locator("vaadin-grid")).containsText("Hi from browser");
+        page.getByLabel("Phone").fill("1");
+        PlaywrightAssertions.assertThat(send).isEnabled();
+
+        page.locator("a", new Page.LocatorOptions().setHasText("About")).click();
+        var keep = page.locator("vaadin-button", new Page.LocatorOptions().setHasText("Keep editing"));
+        keep.click();
+        PlaywrightAssertions.assertThat(page.locator("h1")).hasText("Contact");
+        PlaywrightAssertions.assertThat(page.getByLabel("Phone")).hasValue("1");
+        page.locator("a", new Page.LocatorOptions().setHasText("About")).click();
+        page.locator("vaadin-button", new Page.LocatorOptions().setHasText("Discard")).click();
+        PlaywrightAssertions.assertThat(page.locator("h1")).hasText("About");
+        page.goBack();
+        PlaywrightAssertions.assertThat(page.locator("vaadin-grid")).containsText("Hi from browser");
+
+        // Empty form: leaving is not interrupted
+        page.locator("a", new Page.LocatorOptions().setHasText("About")).click();
+        PlaywrightAssertions.assertThat(page.locator("h1")).hasText("About");
+        assertEquals(0, page.locator("vaadin-dialog[opened]").count());
+        page.close();
+    }
+}
